an Development", "children": [{"id": "1bfe5e11-c25c-4391-9910-d6d33d6c9db7", "type": "concept", "title": "Sensorimotor"}, {"id": "29c7ca08-6962-49f4-94d0-10896c5e3279", "type": "concept", "title": "Preoperational"}, {"id": "0f8a5246-f7ba-4951-a389-694787e7af76", "type": "concept", "title": "Concrete operational"}, {"id": "1e482783-d463-47e7-a420-e7e5bcc10ddf", "type": "concept", "title": "Conservation and classification"}], "description": "Piaget gives a classic account of how children's reasoning changes qualitatively across childhood."}, {"id": "c187e206-e9e6-4564-9f04-689113d0b2d0", "type": "subtopic", "title": "Information Processing", "children": [{"id": "12800dd6-5dbc-49c4-b922-71a64ba509ea", "type": "concept", "title": "Working memory"}, {"id": "785b9ed8-f681-489a-84f2-ae2ca5188d70", "type": "concept", "title": "Processing speed"}, {"id": "3c947206-f193-4651-ba2c-a0440a9707c3", "type": "concept", "title": "Metacognition"}, {"id": "beed0b00-b8ee-4dd2-8db9-4454a5faff10", "type": "concept", "title": "Strategy use"}], "description": "Information-processing approaches explain gradual improvements in attention, memory, strategies, and speed."}, {"id": "20844878-ee8d-4736-8275-51da989afc33", "type": "subtopic", "title": "Executive Function", "children": [{"id": "e5cb474b-038d-413a-82f1-6239f01b8d05", "type": "concept", "title": "Inhibitory control"}, {"id": "7b4b84dd-bd50-4015-b363-9ca4e0f3b20f", "type": "concept", "title": "Cognitive flexibility"}, {"id": "2fa436b7-14e7-4ce8-b122-f0636300c68d", "type": "concept", "title": "Planning"}, {"id": "536370d8-b5aa-44bd-90fe-647537541218", "type": "concept", "title": "Emotion-cognition links"}], "description": "Executive function supports school readiness, self-regulation, planning, and flexible thinking."}]}, {"id": "4e999b4e-7082-4b89-ba0d-ea4d8ff2c3ac", "type": "topic", "title": "Language, Literacy, and Communication Development", "description": "Trace how children acquire language, communication skills, emergent literacy, and multilingual capacities.", "children": [{"id": "51cebde0-e145-45e4-839e-7eda19536d46", "type": "subtopic", "title": "Language Acquisition", "children": [{"id": "4b51a26a-8ffc-4660-b308-cf238d1de97b", "type": "concept", "title": "Phonology"}, {"id": "9f0fb956-6a5f-4a32-9a6a-7b32f637e62c", "type": "concept", "title": "Vocabulary growth"}, {"id": "e174e01e-c94f-4455-b024-a49e8f0c764a", "type": "concept", "title": "Grammar"}, {"id": "43b73839-205e-4721-adde-6a1380564bbe", "type": "concept", "title": "Pragmatics"}], "description": "Language development shows how biology, interaction, cognition, and culture combine."}, {"id": "76e94f67-8665-4551-b8c7-3fb5c3c7523b", "type": "subtopic", "title": "Emergent Literacy", "children": [{"id": "33a1812c-b213-411f-9638-73c26a7452bd", "type": "concept", "title": "Phonological awareness"}, {"id": "c86f33b0-ca62-4760-a9ea-08f4b54eb16e", "type": "concept", "title": "Print concepts"}, {"id": "a00e26ac-4d9f-4fd7-8981-502a6614e2e5", "type": "concept", "title": "Dialogic reading"}, {"id": "deeabbd6-53c6-4232-b4ec-55a475c14999", "type": "concept", "title": "Narrative skills"}], "description": "Early literacy begins before formal reading through talk, books, print awareness, and storytelling."}, {"id": "368826ed-1292-4958-8629-e1d933fad0b1", "type": "subtopic", "title": "Multilingual Development", "children": [{"id": "2a449206-a644-4a7b-a78c-ea46e7915046", "type": "concept", "title": "Home language"}, {"id": "fffa3ee0-a410-4a4a-b7f6-2155268c3083", "type": "concept", "title": "Code-switching"}, {"id": "2a571a5e-a315-43b9-9880-667b29a77792", "type": "concept", "title": "Dual-language learners"}, {"id": "c01bec9f-a36e-4b63-ba7a-d10728271dd3", "type": "concept", "title": "Language-rich environments"}], "description": "Multilingual development is a strength that requires informed, culturally responsive support."}]}, {"id": "b8bb324a-d073-4190-98af-756a7f2eb18e", "type": "topic", "title": "Social-Emotional Development, Emotion Regulation, an