set
  title = 'Child Development',
  goal = 'Child Development',
  summary = 'Frame child development as an evidence-based study of change in children within relationships, cultures, schools, and communities. Topics cover research methods and ethics, major theories, prenatal development and early brain architecture, infancy, attachment, and temperament, physical and health development, cognition and executive function, language and literacy, social-emotional development, family, peers, and developmental relationships, culture and ecological systems, play and motivation, middle childhood and schooling, neurodiversity, risk, resilience, and trauma, and developmentally appropriate practice.',
  data = $chdvjson${"slug": "child-development", "title": "Child Development", "description": "Frame child development as an evidence-based study of change in children within relationships, cultures, schools, and communities. Topics cover research methods and ethics, major theories, prenatal development and early brain architecture, infancy, attachment, and temperament, physical and health development, cognition and executive function, language and literacy, social-emotional development, family, peers, and developmental relationships, culture and ecological systems, play and motivation, middle childhood and schooling, neurodiversity, risk, resilience, and trauma, and developmentally appropriate practice.", "topics": [{"id": "24764b4e-e840-482a-90d0-b71896b1cd84", "type": "topic", "title": "Child Development as a Field: Questions, Methods, and Ethics", "description": "Frame child development as an evidence-based study of change in children within relationships, cultures, schools, and communities.", "children": [{"id": "73d1cd02-5c3f-468a-9c2f-c2534503c48e", "type": "subtopic", "title": "Core Questions", "children": [{"id": "9a5299ee-650f-4eda-b149-50e69c7c3df0", "type": "concept", "title": "Nature and nurture"}, {"id": "940b0f24-3033-41fb-9476-f223cec1dee9", "type": "concept", "title": "Continuity and discontinuity"}, {"id": "aef27e58-5aea-41aa-96bb-3fe3fd3aa2ba", "type": "concept", "title": "Individual differences"}, {"id": "8e486a5f-0b1e-407c-95cd-4e4617167aa5", "type": "concept", "title": "Developmental pathways"}], "description": "Students begin by asking what changes in childhood, why it changes, and how context shapes developmental pathways."}, {"id": "d0a7b883-d67d-42eb-9477-b7789818c9de", "type": "subtopic", "title": "Research Methods with Children", "children": [{"id": "448d138b-2893-4297-8518-3a613ff05bfd", "type": "concept", "title": "Observation"}, {"id": "a707278c-26a7-49bc-abd2-e634ce8c30f2", "type": "concept", "title": "Experiments and quasi-experiments"}, {"id": "5598a43f-1df8-4409-a28b-2bd4c9a3b633", "type": "concept", "title": "Longitudinal and cross-sectional designs"}, {"id": "e9a45b34-b3af-4521-b089-8d48bc2cb063", "type": "concept", "title": "Child assent and caregiver consent"}], "description": "Child development requires methods that fit children's abilities while protecting their rights and dignity."}, {"id": "6b64b24b-e35b-4430-bde4-4f419fd2aa64", "type": "subtopic", "title": "Ethical and Practical Interpretation", "children": [{"id": "e6125a26-6573-4101-b833-11f0ed28d32c", "type": "concept", "title": "Deficit vs strengths framing"}, {"id": "34daa164-21de-44d6-809c-eab3c50adf92", "type": "concept", "title": "Privacy"}, {"id": "c4f574d0-d35e-443f-bb24-6ee08467c691", "type": "concept", "title": "Bias in measurement"}, {"id": "a9d23495-b975-48c1-a395-c84167b7667d", "type": "concept", "title": "Application limits"}], "description": "Developmental findings must be interpreted without labeling children narrowly or ignoring culture and opportunity."}]}, {"id": "8971cc1a-10c8-4ddb-8391-0e615c796ff4", "type": "topic", "title": "Major Theories of Development and Learning", "description": "Compare classic and contemporary theories that explain how children grow, learn, relate, and adapt.", "children": [{"id": "61327478-8986-4a17-a4d4-e1f25c14736d", "type": "subtopic", "title": "Cognitive and Constructivist Theories", "children": [{"id": "9d0bb446-a0d1-4915-9155-f891c4ee5015", "type": "concept", "title": "Piaget"}, {"id": "22ef0ede-091b-422c-97c7-f9acc94097e1", "type": "concept", "title": "Schemas"}, {"id": "777192b2-c664-40a2-984c-9cf80a6a3301", "type": "concept", "title": "Stages"}, {"id": "d0021de4-a780-4586-87f6-7c0ac58c3173", "type": "concept", "title": "Constructivism"}], "description": "Cognitive theories explain how children actively build knowledge through experience and changing mental structures."}, {"id": "ea87dd45-a5a9-4613-af17-4dcad865ef3f", "type": "subtopic", "title": "Sociocultural and Psychosocial Theories", "children": [{"id": "ef0d4bb1-19e7-4654-948c-3dc850304281", "type": "concept", "title": "Vygotsky"}, {"id": "2d70ef8c-b546-4402-8d15-3c79ade6197e", "type": "concept", "title": "Zone of proximal development"}, {"id": "461c69b3-43b6-40b1-acd4-b215b4debe7b", "type": "concept", "title": "Erikson"}, {"id": "e00cdcd5-f933-462e-8806-4142abb042fb", "type": "concept", "title": "Scaffolding"}], "description": "These theories emphasize relationships, culture, language, identity, and social participation."}, {"id": "a10091d1-2a74-4442-933e-ccfdc652894d", "type": "subtopic", "title": "Learning, Ecological, and Systems Theories", "children": [{"id": "6dc5fc2f-f0d8-4f26-9577-cd4886d7faae", "type": "concept", "title": "Behaviorism and social learning"}, {"id": "7fe31fd0-dfaa-4e99-ac44-d0a61caea443", "type": "concept", "title": "Bronfenbrenner"}, {"id": "f6597b3a-8f41-4aa7-9e67-a57c4a103c0d", "type": "concept", "title": "Developmental systems"}, {"id": "57d4d3d0-98e6-452a-acd5-cc78df058174", "type": "concept", "title": "Transactional models"}], "description": "Modern developmental thinking connects learning processes to families, schools, communities, biology, and time."}]}, {"id": "4d86a9bb-e244-48be-b2d4-c93c40665bdb", "type": "topic", "title": "Prenatal Development, Birth, and Early Brain Architecture", "description": "Understand how early biological foundations, environments, and caregiving shape developmental trajectories.", "children": [{"id": "4cba785c-2e6f-4b51-88a9-6a641f3f608f", "type": "subtopic", "title": "Prenatal Development", "children": [{"id": "0f859a70-fa78-4dd8-8f50-6a1cd5e8553e", "type": "concept", "title": "Germinal, embryonic, fetal periods"}, {"id": "1bf19c0b-d0d3-4bac-800c-8b93d40a2025", "type": "concept", "title": "Teratogens"}, {"id": "e61b915a-e85a-4a62-a33c-8dd69bbe0727", "type": "concept", "title": "Maternal health"}, {"id": "bc5dda87-0997-40e5-8c95-a1651d2e66cc", "type": "concept", "title": "Prenatal stress"}], "description": "Prenatal development introduces early biological growth and the sensitivity of developing systems to environments."}, {"id": "18bd2593-ab5a-412c-a40b-502248ec370f", "type": "subtopic", "title": "Birth and Newborn Adaptation", "children": [{"id": "b569df40-eb99-4421-8690-b4726b454da6", "type": "concept", "title": "Labor and delivery overview"}, {"id": "b21d068c-5a37-40eb-92e1-fa85aebe7ff1", "type": "concept", "title": "Prematurity"}, {"id": "d8102e29-a74b-4626-a9be-b7b6b4e057fd", "type": "concept", "title": "Newborn reflexes"}, {"id": "beda6210-5119-4b10-8ce6-97599595fa36", "type": "concept", "title": "Early screening"}], "description": "Birth and early adaptation shape the transition from prenatal life to social, sensory, and caregiving worlds."}, {"id": "1c6dd2cd-61ae-4419-b543-41bc55464701", "type": "subtopic", "title": "Brain Architecture", "children": [{"id": "4ccbf9ee-114f-41ad-a981-07bda10290ff", "type": "concept", "title": "Neurogenesis and synaptogenesis"}, {"id": "c6b8cfee-7b98-4157-adb4-9472eadc4dd3", "type": "concept", "title": "Pruning"}, {"id": "1d1031f4-ca90-400c-8cec-54e8c76cea7b", "type": "concept", "title": "Plasticity"}, {"id": "46bd0cd9-aa32-438d-99fb-4c17a87c7ac7", "type": "concept", "title": "Serve-and-return interaction"}], "description": "Early brain development explains why relationships, safety, sleep, nutrition, and stimulation matter."}]}, {"id": "75780038-43c4-4669-bb49-b5673759bdf0", "type": "topic", "title": "Infancy, Attachment, Temperament, and Early Relationships", "description": "Study how infants develop trust, regulation, communication, and secure relationships.", "children": [{"id": "3749e31f-09d1-408f-9b67-bff95014e13c", "type": "subtopic", "title": "Infant Development", "children": [{"id": "3b1d4cc0-2d57-482a-b632-d8e937f7ae1c", "type": "concept", "title": "Perceptual abilities"}, {"id": "5e0a0ef7-7b09-4b72-a71b-e60425487c8f", "type": "concept", "title": "Motor milestones"}, {"id": "af89dcd8-8104-4673-afbc-8f8848c4ab70", "type": "concept", "title": "Joint attention"}, {"id": "66482e91-f0ed-4840-a581-83e40c1e7630", "type": "concept", "title": "Social referencing"}], "description": "Infancy is a period of rapid change in perception, movement, communication, and social engagement."}, {"id": "808e29d9-8f4b-4534-88f9-fb24e5f95bb0", "type": "subtopic", "title": "Attachment", "children": [{"id": "7d017d4e-9c72-4f4b-b351-13e36aaffbee", "type": "concept", "title": "Bowlby"}, {"id": "04282291-a71b-4afb-baea-5aeb603f43c5", "type": "concept", "title": "Ainsworth"}, {"id": "dd36e53a-8348-42d9-bc4c-58a2266df512", "type": "concept", "title": "Secure and insecure patterns"}, {"id": "96d2c6cc-d67e-447c-be5b-e09bf49e0118", "type": "concept", "title": "Internal working models"}], "description": "Attachment theory explains how early caregiver relationships support exploration, security, and regulation."}, {"id": "4f726a06-22c9-4777-af3b-b2b8632094e6", "type": "subtopic", "title": "Temperament and Regulation", "children": [{"id": "425ae948-80c5-4621-90b1-67b05686bc15", "type": "concept", "title": "Reactivity"}, {"id": "0e3fb564-1976-43b5-ae53-338a0ace1388", "type": "concept", "title": "Self-soothing"}, {"id": "c50ab9b5-7ca8-4797-b51e-6e39f9080819", "type": "concept", "title": "Effortful control"}, {"id": "ca0ea776-eca6-4e56-9310-5175886d4ed2", "type": "concept", "title": "Caregiver responsiveness"}], "description": "Temperament helps explain early individual differences and the importance of goodness of fit."}]}, {"id": "39dc177d-eb43-4411-bd73-89693816ce2a", "type": "topic", "title": "Physical, Motor, Sensory, and Health Development", "description": "Connect growth, movement, sensory development, sleep, nutrition, and health to learning readiness and wellbeing.", "children": [{"id": "8d1653f3-35b1-47e8-bafa-a364aadf5b6b", "type": "subtopic", "title": "Growth and Motor Development", "children": [{"id": "d0766c75-ad5c-4c5c-b6f1-7518313d66f6", "type": "concept", "title": "Gross motor skills"}, {"id": "6380cc49-71d6-495b-9551-efab0dc84d9d", "type": "concept", "title": "Fine motor skills"}, {"id": "78998db4-2bd1-4291-8dc6-ed131a939f32", "type": "concept", "title": "Handwriting readiness"}, {"id": "c114b905-98d2-4270-a2ab-a5dbd66f2aef", "type": "concept", "title": "Motor coordination"}], "description": "Physical and motor growth support independence, exploration, play, and classroom participation."}, {"id": "eae44d44-aa12-4621-bbbd-ee4857238a93", "type": "subtopic", "title": "Sensory Development", "children": [{"id": "09a1fa83-0413-4447-ba4d-27bfa70deeab", "type": "concept", "title": "Vision and hearing"}, {"id": "e4799e38-549b-49cd-bdd5-04b104f355a1", "type": "concept", "title": "Touch and proprioception"}, {"id": "0e93a23f-9e77-4dbc-b8e1-f91806cd655c", "type": "concept", "title": "Sensory integration"}, {"id": "f4de9910-edb2-4623-b51f-7ec4006a96e1", "type": "concept", "title": "Environmental stimulation"}], "description": "Children learn through sensory systems that develop in interaction with movement, attention, and environment."}, {"id": "72b3ad28-cdc9-48ee-99b4-cea6ecff0549", "type": "subtopic", "title": "Health Foundations", "children": [{"id": "76e69873-c313-4e34-ad56-885dc05837f1", "type": "concept", "title": "Sleep routines"}, {"id": "9c3b382c-e180-4e3d-a890-20a8a50d4694", "type": "concept", "title": "Nutrition"}, {"id": "0d22a02f-72d9-44a4-970d-9b27c6edef9e", "type": "concept", "title": "Physical activity"}, {"id": "65d75b84-813f-4a53-b8a7-97157fa6c10a", "type": "concept", "title": "Preventive care and safety"}], "description": "Health, sleep, nutrition, and safety are developmental foundations, not side issues."}]}, {"id": "93aefdce-281f-4012-a812-a45215af701c", "type": "topic", "title": "Cognitive Development: Piaget, Information Processing, and Executive Function", "description": "Explain how children's thinking, memory, attention, problem solving, and self-control change over time.", "children": [{"id": "c46c5b67-ba28-47b4-9819-61a034799d61", "type": "subtopic", "title": "Piagetian Development", "children": [{"id": "1bfe5e11-c25c-4391-9910-d6d33d6c9db7", "type": "concept", "title": "Sensorimotor"}, {"id": "29c7ca08-6962-49f4-94d0-10896c5e3279", "type": "concept", "title": "Preoperational"}, {"id": "0f8a5246-f7ba-4951-a389-694787e7af76", "type": "concept", "title": "Concrete operational"}, {"id": "1e482783-d463-47e7-a420-e7e5bcc10ddf", "type": "concept", "title": "Conservation and classification"}], "description": "Piaget gives a classic account of how children's reasoning changes qualitatively across childhood."}, {"id": "c187e206-e9e6-4564-9f04-689113d0b2d0", "type": "subtopic", "title": "Information Processing", "children": [{"id": "12800dd6-5dbc-49c4-b922-71a64ba509ea", "type": "concept", "title": "Working memory"}, {"id": "785b9ed8-f681-489a-84f2-ae2ca5188d70", "type": "concept", "title": "Processing speed"}, {"id": "3c947206-f193-4651-ba2c-a0440a9707c3", "type": "concept", "title": "Metacognition"}, {"id": "beed0b00-b8ee-4dd2-8db9-4454a5faff10", "type": "concept", "title": "Strategy use"}], "description": "Information-processing approaches explain gradual improvements in attention, memory, strategies, and speed."}, {"id": "20844878-ee8d-4736-8275-51da989afc33", "type": "subtopic", "title": "Executive Function", "children": [{"id": "e5cb474b-038d-413a-82f1-6239f01b8d05", "type": "concept", "title": "Inhibitory control"}, {"id": "7b4b84dd-bd50-4015-b363-9ca4e0f3b20f", "type": "concept", "title": "Cognitive flexibility"}, {"id": "2fa436b7-14e7-4ce8-b122-f0636300c68d", "type": "concept", "title": "Planning"}, {"id": "536370d8-b5aa-44bd-90fe-647537541218", "type": "concept", "title": "Emotion-cognition links"}], "description": "Executive function supports school readiness, self-regulation, planning, and flexible thinking."}]}, {"id": "4e999b4e-7082-4b89-ba0d-ea4d8ff2c3ac", "type": "topic", "title": "Language, Literacy, and Communication Development", "description": "Trace how children acquire language, communication skills, emergent literacy, and multilingual capacities.", "children": [{"id": "51cebde0-e145-45e4-839e-7eda19536d46", "type": "subtopic", "title": "Language Acquisition", "children": [{"id": "4b51a26a-8ffc-4660-b308-cf238d1de97b", "type": "concept", "title": "Phonology"}, {"id": "9f0fb956-6a5f-4a32-9a6a-7b32f637e62c", "type": "concept", "title": "Vocabulary growth"}, {"id": "e174e01e-c94f-4455-b024-a49e8f0c764a", "type": "concept", "title": "Grammar"}, {"id": "43b73839-205e-4721-adde-6a1380564bbe", "type": "concept", "title": "Pragmatics"}], "description": "Language development shows how biology, interaction, cognition, and culture combine."}, {"id": "76e94f67-8665-4551-b8c7-3fb5c3c7523b", "type": "subtopic", "title": "Emergent Literacy", "children": [{"id": "33a1812c-b213-411f-9638-73c26a7452bd", "type": "concept", "title": "Phonological awareness"}, {"id": "c86f33b0-ca62-4760-a9ea-08f4b54eb16e", "type": "concept", "title": "Print concepts"}, {"id": "a00e26ac-4d9f-4fd7-8981-502a6614e2e5", "type": "concept", "title": "Dialogic reading"}, {"id": "deeabbd6-53c6-4232-b4ec-55a475c14999", "type": "concept", "title": "Narrative skills"}], "description": "Early literacy begins before formal reading through talk, books, print awareness, and storytelling."}, {"id": "368826ed-1292-4958-8629-e1d933fad0b1", "type": "subtopic", "title": "Multilingual Development", "children": [{"id": "2a449206-a644-4a7b-a78c-ea46e7915046", "type": "concept", "title": "Home language"}, {"id": "fffa3ee0-a410-4a4a-b7f6-2155268c3083", "type": "concept", "title": "Code-switching"}, {"id": "2a571a5e-a315-43b9-9880-667b29a77792", "type": "concept", "title": "Dual-language learners"}, {"id": "c01bec9f-a36e-4b63-ba7a-d10728271dd3", "type": "concept", "title": "Language-rich environments"}], "description": "Multilingual development is a strength that requires informed, culturally responsive support."}]}, {"id": "b8bb324a-d073-4190-98af-756a7f2eb18e", "type": "topic", "title": "Social-Emotional Development, Emotion Regulat